			hint = "Mark the towers of Andorhal for the assault.",
			unlock = {
				{ type = "quest", id = 5097 },
			},
			text = [=[The {link:scourge}Scourge{/link} used four watchtowers to guide its forces through {link:ruins-of-andorhal}Andorhal{/link}. Valorfist had a beacon torch made, and with it the towers were marked one by one. His priests felt the beacons burning strong. The commander declared that the time had come to take the fight into the city.]=],
