Add({
	kind = "figure",
	id = "chromie",
	title = "Chromie",
	subtitle = "The Strange Historian",
	tier = "B",
	region = "western-plaguelands",
	npc = { 10667 },
	allegiance = "Unknown",
	found = "The ruined inn at the north-west corner of Andorhal",
	pin = { x = 39.5, y = 66.8 },
	unlock = {
		{ type = "interact" },
	},
	hint = [=[Seek the gnome woman who lives in the ruined inn of Andorhal.]=],
	sections = {
		{
			title = "Summary",
			text = [=[Chromie is a small {link:gnomes}gnome{/link} woman who has made her home in the ruined inn of {link:ruins-of-andorhal}Andorhal{/link}, in a city held by the dead. The room she keeps is strangely whole, as if the ruin around it had not touched it. She speaks of time as other folk speak of weather. She asks travellers whether they come from the future, and she does not seem to be joking.]=],
		},
		{
			title = "Significance",
			text = [=[Chromie claims that something has tampered with the flow of time in {link:ruins-of-andorhal}Andorhal{/link}, and that she has come to mend it. Whatever she is, she knows far more than a {link:gnomes}gnome{/link} should about the city's past, and about the fates of those who died in the war.]=],
		},
		{
			title = "Deeds",
			text = [=[• She keeps a room in the ruined inn of {link:ruins-of-andorhal}Andorhal{/link}.
• She hunts the creatures that feed on the broken flow of time in the city.
• She gathers the stopped watches of Andorhal.
• She seeks to learn the fate of {link:joseph-redpath}Joseph Redpath{/link} of {link:darrowshire}Darrowshire{/link}, and to change it.]=],
		},
	},
	chapters = {
		{
			key = "a-matter-of-time",
			title = "A Matter of Time",
			hint = [=[Help the gnome in the inn with the parasites of Andorhal's silos.]=],
			unlock = {
				{ type = "quest", id = 4971 },
			},
			text = [=[Chromie said that the timeline of {link:ruins-of-andorhal}Andorhal{/link} had been tampered with, most likely by the {link:scourge}Scourge{/link}. Creatures that feed on broken time had gathered in the silos, and they troubled her work. When they were rooted out, she spoke more openly. She is not a {link:gnomes}gnome{/link} at all. She serves the bronze dragonflight, the keepers of time, and her true shape is hidden.]=],
		},
		{
			key = "counting-out-time",
			title = "Counting Out Time",
			hint = "Bring the stopped watches of Andorhal to Chromie.",
			unlock = {
				{ type = "quest", id = 4972 },
			},
			text = [=[To mend the damage to {link:ruins-of-andorhal}Andorhal{/link}, Chromie works from a different thread of time, so as not to disturb it further. She needs trinkets from the moment the plague struck. The watches of the city serve, for all of them stopped at three o'clock, the hour the plague first spread. What Chromie gives in return are gifts whose use, she says, will become clear in time.]=],
		},
		{
			key = "the-annals-of-darrowshire",
			title = "The Annals of Darrowshire",
			hint = "Find the chronicle of Darrowshire in Andorhal's city hall.",
			unlock = {
				{ type = "quest", id = 5154 },
			},
			text = [=[The ghost of {link:marlene-redpath}Marlene Redpath{/link} sent a ring to Chromie, the wedding ring of {link:joseph-redpath}Joseph Redpath{/link}. Chromie knew at once that it had belonged to a great man with a tragic past. The Annals of {link:darrowshire}Darrowshire{/link}, kept in the city hall of {link:ruins-of-andorhal}Andorhal{/link}, told the rest: in the battle for Darrowshire, Joseph was corrupted and turned against its defenders. Chromie resolved to change that fate if she could.]=],
		},
	},
	mentions = {
		{
			text = "A Matter of Time",
			unlock = {
				{ type = "quest", id = 4971 },
			},
		},
